/// <summary>
/// CB223_PalletRounding
/// Pallet rounding logic for a sales order.
/// </summary>
internal final class METSalesTablePalletRoundingProcess
{
    SalesId salesId;
}

Method.Source:
/// <summary>
/// Construct
/// </summary>
/// <param name = "_salesTable">Sales order header</param>
/// <returns>New instance of <c>METSalesTablePalletRoundingProcess</c> class</returns>
static METSalesTablePalletRoundingProcess construct(SalesId _salesId)
{
    if (!_salesId)
    {
        throw error(strFmt("@SYS19306", funcName()));
    }
    
    return new METSalesTablePalletRoundingProcess(_salesId);
}

/// <summary>
/// New method
/// </summary>
/// <param name = "_salesTable">Sales order header</param>
protected void new(SalesId _salesId)
{
    salesId = _salesId;
}

    /// <summary>
    /// Run the sales order pallet rounding
    /// </summary>
    void run()
    {
        SalesLine                           salesLineLoop;
        InventDim                           inventDim;
        METSalesLinePalletRoundingProcess   palletRoundingSalesLineProcess;

        // group and sum qty by item 
        // Check 2: Accumulate Item’s quantities within a Sales order 
        // (one item may occur multiple time within a single Sales order due to bonus stock functionality)
        while select ItemId, CustAccount, SalesUnit, sum(SalesQty) 
            from salesLineLoop
                group by ItemId, CustAccount, SalesUnit
                join InventSiteId from inventDim
                group by InventSiteId
                where inventDim.inventDimId == salesLineLoop.InventDimId
                   && salesLineLoop.SalesId == salesId             
        {          
            setPrefix(strFmt("Pallet rounding - Sales order %1, item %2, customer %3, unit %4, site %5", salesId,
                                                                                                         salesLineLoop.ItemId,
                                                                                                         salesLineLoop.CustAccount,
                                                                                                         salesLineLoop.SalesUnit,
                                                                                                         inventDim.InventSiteId));

            // Process salesLine for pallet rounding
            palletRoundingSalesLineProcess = METSalesLinePalletRoundingProcess::construct(salesId,
                                                                                salesLineLoop.ItemId,
                                                                                salesLineLoop.CustAccount,
                                                                                salesLineLoop.SalesUnit,
                                                                                salesLineLoop.SalesQty,
                                                                                inventDim.InventSiteId);
            palletRoundingSalesLineProcess.run();            
        }
    }
